import type { Token } from "./tokenizer";
export type Stylesheet = {
    scene: SceneElement[];
    rules: Rule[];
    keyframes: Keyframes[];
    properties: PropertyRule[];
    panels: PanelRule[];
    paints: PaintRule[];
};
export type PaintRule = {
    at: Token;
    name: Token;
    code: Token;
    line?: number;
};
export type PanelRule = {
    at: Token;
    descriptors: Declaration[];
};
export type PropertyRule = {
    name: Token;
    descriptors: Declaration[];
};
export type SceneElement = {
    tag: string;
    id: string | null;
    classes: string[];
    attributes?: Record<string, string>;
    count: number;
    children?: SceneElement[];
};
export type Rule = {
    selector: Token[];
    declarations: Declaration[];
    media?: string;
};
export type Declaration = {
    property: string;
    value: Token[];
    important?: boolean;
};
export type Keyframes = {
    name: string;
    frames: Keyframe[];
};
export type Keyframe = {
    offsets: Token[];
    declarations: Declaration[];
};
